import{_ as e,o as d,c as n,ag as a}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Einstellungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/repair-station/settings.md","filePath":"de/repair-station/settings.md"}'),r={name:"de/repair-station/settings.md"};function i(o,t,s,h,c,l){return d(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h1><p>Jede Einstellung der Repair Station wird in <code>/nay</code> bearbeitet, auf der Seite <strong>Repair Station</strong> (Scope <code>nay_repair.config</code>). Änderungen werden in der Datenbank gespeichert und sofort für alle Spieler übernommen. <code>config.lua</code> enthält optionale Startwerte: Sie gelten, bis eine Einstellung in <code>/nay</code> geändert wird, und <strong>Zurücksetzen</strong> geht auf sie zurück.</p><p>Die Spalte <strong>In /nay</strong> zeigt den Namen, der im Panel angezeigt wird. Der Schlüssel ist der Name, den <code>config.lua</code> und die <a href="/de/nay-lib/api">HTTP-API</a> verwenden.</p><h2 id="allgemein" tabindex="-1">Allgemein <a class="header-anchor" href="#allgemein" aria-label="Permalink to &quot;Allgemein&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Aktiviert</td><td><code>Enabled</code></td><td>an / aus</td><td>an</td><td>Schaltet alle Stationen ein oder aus.</td></tr><tr><td>Zahlungskonto</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> oder <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Von wo der Preis abgebucht wird. <code>cash_then_bank</code> nutzt die Bank, wenn das Bargeld nicht reicht.</td></tr><tr><td>Job-Rabatte</td><td><code>JobDiscounts</code></td><td>Liste, bis zu 32</td><td>keine</td><td>Rabatte für einen Job ab einem Rang.</td></tr><tr><td>Wartezeit (Sekunden)</td><td><code>CooldownSeconds</code></td><td>Sekunden, 0 bis 3600</td><td>0</td><td>Mindestwartezeit zwischen zwei Reparaturen desselben Spielers. 0 schaltet sie aus.</td></tr></tbody></table><p>Einträge unter <strong>Job-Rabatte</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Job</td><td><code>Job</code></td><td>Text, 1 bis 32 Zeichen</td><td>Name des Jobs, wie in deinem Framework.</td></tr><tr><td>Mindestrang</td><td><code>MinGrade</code></td><td>Zahl, 0 bis 100</td><td>Niedrigster Rang, der den Rabatt bekommt.</td></tr><tr><td>Rabatt (%)</td><td><code>Percent</code></td><td>Zahl, 1 bis 100</td><td>Rabatt in Prozent. 100 macht die Reparatur kostenlos.</td></tr></tbody></table><h2 id="leistungen" tabindex="-1">Leistungen <a class="header-anchor" href="#leistungen" aria-label="Permalink to &quot;Leistungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Reparaturleistungen</td><td><code>Services</code></td><td>Liste, 1 bis 8</td><td>Motorreparatur 250 $, Karosserie und Reifen 400 $, Komplettreparatur 700 $</td><td>Leistungen, die in jeder Station angeboten werden.</td></tr><tr><td>Preis nach Schaden</td><td><code>PriceByDamage</code></td><td>an / aus</td><td>an</td><td>Passt den Preis dem Schaden der reparierten Teile an.</td></tr><tr><td>Mindestpreis (%)</td><td><code>MinPricePercent</code></td><td>Zahl, 0 bis 100</td><td>20</td><td>Niedrigster Anteil des Leistungspreises beim Preis nach Schaden.</td></tr><tr><td>Unbeschädigte Fahrzeuge ablehnen</td><td><code>RequireDamage</code></td><td>an / aus</td><td>an</td><td>Lehnt eine Leistung ab, wenn die Teile, die sie repariert, intakt sind.</td></tr><tr><td>Gesperrte Fahrzeugklassen</td><td><code>BlockedClasses</code></td><td>Liste von Fahrzeugklassen</td><td>Fahrräder, Boote, Hubschrauber, Flugzeuge, Züge</td><td>Fahrzeugklassen, die an der Station abgelehnt werden.</td></tr></tbody></table><p>Einträge unter <strong>Reparaturleistungen</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Name</td><td><code>Label</code></td><td>Text, bis zu 32 Zeichen</td><td>Name im Reparaturmenü, im Verlauf und in Webhooks. Optional: Leer erhält die Leistung den Namen der reparierten Teile in der Serversprache (Motorreparatur, Karosserie und Reifen, Komplettreparatur...).</td></tr><tr><td>Preis</td><td><code>Price</code></td><td>Zahl, 0 bis 1000000</td><td>Preis bei vollem Schaden, vor Rabatten und dem Stationsprozentsatz.</td></tr><tr><td>Dauer (Sekunden)</td><td><code>Seconds</code></td><td>Zahl, 3 bis 120</td><td>Wie lange die Reparatur dauert.</td></tr><tr><td>Repariert den Motor</td><td><code>Engine</code></td><td>an / aus</td><td>Schließt den Tank ein.</td></tr><tr><td>Repariert die Karosserie</td><td><code>Body</code></td><td>an / aus</td><td>Schließt Scheiben, Türen und Verformungen ein.</td></tr><tr><td>Repariert die Reifen</td><td><code>Tyres</code></td><td>an / aus</td><td>Repariert alle geplatzten Reifen.</td></tr></tbody></table><p>Bei aktivem <code>PriceByDamage</code> ist der Preis der Leistungspreis mal dem höchsten Schaden der Teile, die sie repariert, nie unter <code>MinPricePercent</code> und nie über 100 Prozent. Danach gelten der Stationsprozentsatz und der Job-Rabatt. Ausgeschaltet wird immer der volle Preis berechnet.</p><p>Einträge unter <strong>Gesperrte Fahrzeugklassen</strong> haben ein einziges Feld, <strong>Klasse</strong> (<code>Class</code>), ausgewählt aus den GTA-Fahrzeugklassen nach Name.</p><h2 id="stations" tabindex="-1">Stationen <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stationen {#stations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Stationen</td><td><code>Stations</code></td><td>Liste, bis zu 64</td><td>Hayes Autos, Sandy Shores, Paleto Bay</td><td>Die Stationen. Platziert mit dem <a href="/de/repair-station/stations">Stationseditor</a>.</td></tr></tbody></table><p>Einträge lassen sich leichter mit dem <a href="/de/repair-station/stations">Stationseditor</a> bearbeiten, der diese Felder für dich füllt:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Kennung</td><td><code>Id</code></td><td>Text, 8</td><td>8 Zeichen (0 bis 9, a bis f), vom Editor vergeben. Muss eindeutig sein.</td></tr><tr><td>Name</td><td><code>Label</code></td><td>Text, bis zu 48 Zeichen</td><td>Im Hinweis, im Verlauf und in Webhooks angezeigt. Optional.</td></tr><tr><td>Geöffnet</td><td><code>Enabled</code></td><td>an / aus</td><td>Schließt eine Station, ohne sie zu löschen.</td></tr><tr><td>Fahrzeugposition</td><td><code>Coords</code></td><td>Position und Ausrichtung</td><td>Wo Fahrzeuge halten, mit der Ausrichtung.</td></tr><tr><td>Radius (m)</td><td><code>Radius</code></td><td>Meter, 1,5 bis 6</td><td>Wie weit von der Position ein Fahrzeug noch in der Station ist.</td></tr><tr><td>Preis (%)</td><td><code>PricePercent</code></td><td>Zahl, 0 bis 1000</td><td>Prozentsatz, der in dieser Station auf jeden Preis angewendet wird. 100 behält die Preise bei.</td></tr><tr><td>Prop-Modell</td><td><code>Prop</code></td><td>Text, bis zu 64 Zeichen</td><td>Prop neben der Station. Optional.</td></tr><tr><td>Prop-Position</td><td><code>PropCoords</code></td><td>Position und Ausrichtung</td><td>Wo das Prop steht. Optional.</td></tr><tr><td>Kartenblip</td><td><code>Blip</code></td><td>an / aus</td><td>Zeigt diese Station auf der Karte.</td></tr></tbody></table><h2 id="mechaniker" tabindex="-1">Mechaniker <a class="header-anchor" href="#mechaniker" aria-label="Permalink to &quot;Mechaniker&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Mechaniker-Jobs</td><td><code>MechanicJobs</code></td><td>Liste, bis zu 16</td><td><code>mechanic</code></td><td>Jobs, die als Mechaniker im Dienst zählen.</td></tr><tr><td>Limit für Mechaniker im Dienst</td><td><code>MaxMechanicsOnDuty</code></td><td>Zahl, 0 bis 64</td><td>0</td><td>Stationen schließen, solange so viele Mechaniker oder mehr im Dienst sind. 0 schließt sie nie.</td></tr></tbody></table><p>Einträge unter <strong>Mechaniker-Jobs</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Job</td><td><code>Job</code></td><td>Text, 1 bis 32 Zeichen</td><td>Name des Jobs, wie in deinem Framework.</td></tr></tbody></table><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Blips anzeigen</td><td><code>ShowBlips</code></td><td>an / aus</td><td>an</td><td>Zeigt die Stationen mit Blip auf der Karte.</td></tr><tr><td>Blip-Symbol</td><td><code>BlipSprite</code></td><td>Blip-Symbol</td><td>446</td><td>Ausgewählt aus einer visuellen Liste von Symbolen. Für einen eigenen Blip kann weiterhin jede Nummer eingegeben werden.</td></tr><tr><td>Blip-Farbe</td><td><code>BlipColor</code></td><td>Blip-Farbe</td><td>47</td><td>Ausgewählt aus einer visuellen Liste von Farben.</td></tr><tr><td>Blip-Größe</td><td><code>BlipScale</code></td><td>0,2 bis 2</td><td>0,8</td><td>Größe des Blips.</td></tr></tbody></table>',23)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
